import os
import re
import sys

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INVOICES = os.path.join(BASE, 'invoices.csv')
PAYMENTS = os.path.join(BASE, 'payments.csv')
BALANCES = os.path.join(BASE, 'balances.csv')
REJECTED = os.path.join(BASE, 'rejected.csv')
INTEGER_CENTS = re.compile(r'^[+-]?[0-9]+$')


def parse_cents(value):
    value = value.strip()
    if not INTEGER_CENTS.match(value):
        raise ValueError('amount is not an integer number of cents')
    return int(value, 10)


def read_rows(path):
    handle = open(path, 'rb')
    try:
        return list(csv.DictReader(handle))
    finally:
        handle.close()


def write_csv(path, fieldnames, rows):
    temporary = path + '.tmp'
    handle = open(temporary, 'wb')
    try:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, extrasaction='ignore')
        writer.writeheader()
        writer.writerows(rows)
        handle.flush()
        os.fsync(handle.fileno())
    finally:
        handle.close()
    os.rename(temporary, path)


def reject(rejected, payment_id, invoice_id, amount_cents, reason):
    rejected.append({
        'payment_id': payment_id,
        'invoice_id': invoice_id,
        'amount_cents': amount_cents,
        'reason': reason,
    })


def main():
    invoices = {}
    invoice_order = []
    rejected = []

    for row in read_rows(INVOICES):
        invoice_id = (row.get('invoice_id') or '').strip()
        raw_amount = row.get('total_cents') or ''
        if not invoice_id:
            reject(rejected, '', invoice_id, raw_amount, 'missing_invoice_id')
            continue
        if invoice_id in invoices:
            reject(rejected, '', invoice_id, raw_amount, 'duplicate_invoice_id')
            continue
        try:
            invoices[invoice_id] = parse_cents(raw_amount)
        except ValueError:
            reject(rejected, '', invoice_id, raw_amount, 'malformed_invoice_amount')
            continue
        invoice_order.append(invoice_id)

    seen_payment_ids = set()
    for row in read_rows(PAYMENTS):
        payment_id = (row.get('payment_id') or '').strip()
        invoice_id = (row.get('invoice_id') or '').strip()
        raw_amount = row.get('amount_cents') or ''

        if not payment_id:
            reject(rejected, payment_id, invoice_id, raw_amount, 'missing_payment_id')
            continue
        if payment_id in seen_payment_ids:
            reject(rejected, payment_id, invoice_id, raw_amount, 'duplicate_payment_id')
            continue
        seen_payment_ids.add(payment_id)

        if invoice_id not in invoices:
            reject(rejected, payment_id, invoice_id, raw_amount, 'unknown_invoice_id')
            continue
        try:
            amount = parse_cents(raw_amount)
        except ValueError:
            reject(rejected, payment_id, invoice_id, raw_amount, 'malformed_amount')
            continue
        invoices[invoice_id] -= amount

    balances = [
        {'invoice_id': invoice_id, 'outstanding_cents': str(invoices[invoice_id])}
        for invoice_id in invoice_order
    ]
    write_csv(BALANCES, ['invoice_id', 'outstanding_cents'], balances)
    write_csv(REJECTED, ['payment_id', 'invoice_id', 'amount_cents', 'reason'], rejected)
    return 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (IOError, OSError, csv.Error, KeyError, ValueError) as error:
        print('reconcile: %s' % error, file=sys.stderr)
        sys.exit(1)
